  "ExplanationCorrect": "Under relevant costing principles, only costs that differ between alternatives (accept vs. reject) are relevant. At idle capacity: Variable manufacturing costs ($16+$12+$6=$34 per unit) are relevant because they will be incurred only if the order is accepted. The additional shipping and customs cost ($3 per unit) is incremental to the special order. Total relevant cost = $34 + $3 = $37 per unit. Relevant revenue = $42 per unit. Contribution margin = $42 − $37 = $5 per unit × 5,000 units = $25,000 total incremental operating income. Fixed overhead ($10 per unit) is irrelevant — it is a committed cost that will be incurred regardless of the decision. Capacity is available (85% utilization), so accepting the special order does not displace normal sales. The special order increases operating income by $25,000 and should be accepted.",
