  "DifficultyScore": 3,
  "ExplanationCorrect": "When a single resource is constrained, products should be ranked by contribution margin per unit of the constrained resource, not by per-unit CM. CM per machine hour: X = $45/3 = $15.00 per hour; Y = $30/1.5 = $20.00 per hour. Y generates $5 more CM per scarce machine hour than X, so it should be prioritized. Step 1: Produce maximum Y = 300 units, consuming 300 × 1.5 = 450 hours, generating CM of 300 × $30 = $9,000. Step 2: Remaining hours = 600 − 450 = 150. Produce X = 150/3 = 50 units (well below its demand cap of 150), generating CM of 50 × $45 = $2,250. Total CM = $9,000 + $2,250 = $11,250. The common error is ranking by per-unit CM: X's $45 > Y's $30, which would lead to producing 150 X first (450 hours, $6,750 CM), then 100 Y with the remaining 150 hours ($3,000 CM), for a total of $9,750 — $1,500 less than the optimal mix. When resources are constrained, relative efficiency (CM per constraint unit) drives the decision, not absolute profitability per unit.",
  "ExplanationWrongA": "Producing 150 X and 100 Y uses 150×3+100×1.5=450+150=600 hours correctly, but ranks by per-unit CM ($45 vs. $30) rather than CM per hour ($15 vs. $20). This yields CM = (150×$45)+(100×$30) = $6,750+$3,000 = $9,750 — $1,500 below the optimum achievable by ranking products by efficiency on the constrained resource.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "Equal allocation ignores that the products have different efficiencies on the constrained resource. Using 300 hours each: X = 300/3 = 100 units ($4,500 CM); Y = 300/1.5 = 200 units ($6,000 CM). Total = $10,500 — better than prioritizing X but still $750 below optimum. Arbitrary equal splits are never optimal unless the CM/constraint ratios happen to be equal.",
