  "DifficultyScore": 3,
  "ExplanationCorrect": "Expected Monetary Value (EMV) = Σ(Probability × Outcome). Strategy A: EMV = 0.60($8M) + 0.40(−$2M) = $4.80M − $0.80M = $4.00M. Strategy B: EMV = 0.50($15M) + 0.50(−$5M) = $7.50M − $2.50M = $5.00M. Strategy B has the higher EMV by $1.0M. While Strategy B carries higher risk (potential $5M loss vs. $2M loss), the EMV framework assumes risk neutrality — the decision-maker maximizes expected value without adjusting for risk preferences. In practice, a risk-averse CEO might prefer Strategy A despite its lower EMV if the company cannot absorb a $5M loss. The EMV analysis provides the starting point for decision-making; risk preferences and the company's financial capacity to absorb losses are layered on top of the EMV calculation.",
