  "DifficultyScore": 3,
  "ExplanationCorrect": "Make-vs-buy decisions involve both quantitative and qualitative dimensions. Quantitative: Relevant cost to make = ($25 × 20,000) + $40,000 avoidable fixed = $540,000. Relevant cost to buy = ($22 × 20,000) − $50,000 sublease = $440,000 − $50,000 = $390,000. Quantitative advantage to outsourcing = $540,000 − $390,000 = $150,000. Qualitative: A 3.2/5 quality rating means approximately 64% satisfaction — below typical acceptance thresholds. A 12% missed delivery rate means approximately 2,400 units per year could arrive late, potentially halting production lines. At $25 per unit in-house cost, even a 15% effective cost increase from quality/delivery issues (inspection, rework, production stoppages, customer penalties) would add approximately $66,000, partially offsetting the $150,000 savings. The correct approach is to quantify the expected cost of supplier failures, add it to the purchase price, and compare the total expected cost against in-house production — not to dismiss the supplier based on qualitative factors alone or to accept the bid ignoring those factors.",
  "ExplanationWrongA": "Outsourcing immediately ignores material qualitative risks that could transform a $150,000 annual saving into a net loss. Contract provisions and penalty clauses provide legal recourse but do not prevent production stoppages. A supplier 6,000 miles away with a documented history of quality and delivery problems requires more rigorous evaluation before commitment.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "Qualitative factors do not always outweigh quantitative analysis — they provide additional data points that should be quantified where possible and compared against the financial impact. A categorical dismissal of cost savings ignores the possibility that the supplier's problems are correctable or that the savings exceed the expected cost of quality and delivery failures. The analytically rigorous approach quantifies the risks.",
  "ExplanationWrongD": "A 50/50 split may be suboptimal. Maintaining two supply sources adds coordination costs, may disqualify volume discounts, and leaves the company exposed to the same supplier risks on half its volume. If the supplier is too risky for 100%, it may also be too risky for 50%. The decision should be based on the total expected cost comparison, not an arbitrary split.",
