  "DifficultyScore": 3,
  "ExplanationCorrect": "The contribution-maximizing price is not the highest per-unit margin price nor the highest-volume price — it is the price where total CM = Units × (Price − VC) is maximized. Computing each price point: $100: 4,000 × ($100−$40) = $240,000. $90: 5,500 × ($90−$40) = $275,000. $80: 7,500 × ($80−$40) = $300,000. $70: 9,000 × ($70−$40) = $270,000. The maximum total CM of $300,000 occurs at $80. The optimal price balances two opposing forces: lower prices increase unit volume (through price elasticity) but reduce per-unit contribution. At $80, moving up to $90 loses 2,000 units × $40 CM ($80,000 lost) while gaining $10 per unit on 5,500 units ($55,000 gained) — net loss of $25,000. Moving down to $70 gains 1,500 units × $30 CM ($45,000 gained) while losing $10 per unit on 7,500 units (−$75,000) — net loss of $30,000. $80 is the optimum because neither a price increase nor decrease improves total CM.",
  "ExplanationWrongA": "$100 maximizes per-unit CM ($60) but at the cost of the lowest unit volume (4,000). The total CM of $240,000 is $60,000 below the optimum at $80. Per-unit margin is only half the equation — volume response to price changes determines whether higher per-unit margins translate to higher total profits.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "The midpoint is not inherently optimal. The optimal price depends on the specific demand schedule and variable cost — it is the price where the incremental volume gain from the next price cut no longer exceeds the per-unit margin sacrificed. At $80, total CM is $300K; at $90, it's $275K — the $90 price is not the optimum.",
  "ExplanationWrongD": "$70 maximizes unit volume (9,000) but at the lowest per-unit CM ($30). Total CM is $270,000 — $30,000 below the optimum at $80. The additional 1,500 units gained from the $80→$70 price cut contribute only $30 each ($45,000 total), while the 7,500 inframarginal units each lose $10 ($75,000 total). Maximizing volume at the expense of margin is no more valid than maximizing margin at the expense of volume.",
