  "ExplanationCorrect": "Under the Theory of Constraints, the bottleneck (constraint) determines the throughput of the entire system. Step 1: Identify the bottleneck — the workstation with the lowest capacity. WS1: 12 units/hr; WS2: 8 units/hr (bottleneck); WS3: 10 units/hr. Step 2: Compute throughput per unit (selling price minus direct materials — only truly variable costs): Alpha = $300−$120 = $180; Beta = $250−$100 = $150. Step 3: Compute throughput per constraint minute: Alpha = $180/30 min = $6.00/min; Beta = $150/15 min = $10.00/min. Beta generates 67% more throughput per minute of the constrained resource. Prioritize Beta: produce as much Beta as demand allows, then fill remaining bottleneck capacity with Alpha. Throughput accounting differs from traditional cost accounting — it treats only direct materials as variable; direct labor and overhead are considered operating expenses (fixed in the short run). The goal is to maximize throughput (S − TVC) per unit of the constrained resource.",
