  "ExplanationWrongD": "Covering operating expenses is a function of total throughput across all products, not per-unit throughput. The priority decision at the bottleneck determines total system throughput. Maximizing throughput per constraint minute maximizes total throughput, which is the fastest path to covering operating expenses. Focusing on per-unit throughput without considering constraint consumption leads to suboptimal product mix decisions.",
