  "CognitiveLevel": "Evaluate",
  "CommonTrapReference": "Assuming all three criteria produce the same recommendation — they embody different risk attitudes (",
  "CorrectChoice": "B",
  "Difficulty": "Difficult",
  "DifficultyScore": 4,
  "ExplanationCorrect": "Under uncertainty without probabilities, decision criteria reflect different attitudes toward risk. Maximax (optimistic): choose the strategy with the highest possible payoff across all states. Best payoffs: S1=$25M, S2=$18M, S3=$12M. Select S1 ($25M). Maximin (pessimistic): choose the strategy with the highest minimum payoff (best of the worst cases). Minimum payoffs: S1=−$5M, S2=$2M, S3=$6M. Select S3 ($6M). Minimax regret: compute the opportunity loss (regret) for each strategy in each state — the difference between the best possible payoff in that state and the strategy's payoff. Then select the strategy that minimizes the maximum regret. Regret table: Boom regrets: S1=$0, S2=$7M, S3=$13M. Normal regrets: S1=$2M, S2=$0, S3=$4M. Recession regrets: S1=$11M, S2=$4M, S3=$0. Maximum regret per strategy: S1=11, S2=7, S3=13. Minimax selects S2 (max regret = $7M). The three criteria give three different answers — maximax (S1, aggressive), maximin (S3, conservative), and minimax regret (S2, balanced) — illustrating that decision strategy depends on risk attitude.",
  "ExplanationWrongA": "Correct for maximax and maximin, but assert S1 for minimax regret. S1's maximum regret is $11M (Recession), which is higher than S2's $7M. Minimax regret selects S2, not S1.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "Maximax selects the highest possible payoff regardless of risk — S1 at $25M, not S2 at $18M. Maximin selects the best worst-case — S3 at $6M, not S2 at $2M. Maximax and maximin are defined by extreme optima, not the middle strategy.",
  "ExplanationWrongD": "The three criteria select three different strategies: S1 (maximax), S3 (maximin), S2 (minimax regret). They are not unanimous. This is common — different decision criteria applied to the same payoff table frequently produce different recommendations because they embody different risk preferences. The lack of unanimity forces the decision-maker to articulate their risk tolerance before selecting a criterion.",
