  "ExplanationCorrect": "Sensitivity analysis is one-variable-at-a-time: hold everything else constant, vary a single input (price, volume, rate), and measure the outcome's response — it isolates drivers but ignores correlated changes. Scenario analysis constructs coherent multi-variable states (optimistic, base, pessimistic) in which inputs move together consistently — fewer cases, but internally consistent. Neither method removes uncertainty; both quantify exposure to it. The two are complementary in Crestline's capital planning review.",
