  "ExplanationCorrect": "EVSI measures what imperfect information adds over deciding without it. Without the test: EV(launch) = 0.5($40) + 0.5(−$20) = $10M; not launching yields $0, so the baseline is $10M. Test accuracy: P(positive | strong) = 0.8, P(positive | weak) = 0.2. P(positive) = (0.8 × 0.5) + (0.2 × 0.5) = 0.5; likewise P(negative) = 0.5. Given a positive result, P(strong) = (0.8 × 0.5) ÷ 0.5 = 0.8, so EV(launch | positive) = 0.8($40) + 0.2(−$20) = $28M — launch. Given a negative result, P(strong) = 0.2, EV(launch | negative) = 0.2($40) + 0.8(−$20) = −$8M — do not launch. EV with test = 0.5($28) + 0.5($0) = $14M. EVSI = $14M − $10M = $4M — the most the firm should pay for the test.",
