  "ExplanationCorrect": "Under CVP analysis, the breakeven point in units equals total fixed costs divided by the contribution margin per unit. The automation proposal raises fixed costs to $300,000 and cuts variable costs to $8, so CM per unit = $20 − $8 = $12. Breakeven units = $300,000 ÷ $12 = 25,000 units. The plan therefore LOWERS Riverton Foods' breakeven point from 30,000 to 25,000 units — 5,000 fewer units must be sold to cover costs. The trade-off is operating leverage: with $300,000 of fixed costs instead of $180,000, profit swings far more sharply with each change in sales volume, so the lower breakeven comes with greater earnings risk. A common error is reusing the old 30,000-unit breakeven, or dividing fixed costs by variable cost ($300,000 ÷ $8 = 37,500) instead of the contribution margin.",
