  "ExplanationWrongC": "37,500 units results from dividing the new fixed costs by the new variable cost per unit: $300,000 ÷ $8 = 37,500. Variable cost is the outflow per unit, not the margin available to cover fixed costs. The correct divisor is the contribution margin of $12 ($20 − $8). A candidate reaching this answer has confused cost per unit with margin per unit.",
