  "CorrectChoice": "A",
  "Difficulty": "Difficult",
  "DifficultyScore": 4,
  "ExplanationCorrect": "A profit-maximizing price-setter produces where marginal revenue equals marginal cost. With linear demand P = 60 − 0.005Q, marginal revenue has twice the slope: MR = 60 − 0.01Q. Setting MR = MC: 60 − 0.01Q = 20 → 0.01Q = 40 → Q = 4,000 units. At 4,000 units the price is P = 60 − 0.005(4,000) = $40. Valentis earns its maximum profit because each unit up to 4,000 adds more to revenue than its $20 cost, and each unit beyond 4,000 adds less than $20. A common error is setting price equal to marginal cost (P = MC, giving 8,000 units) — that rule applies to price-TAKING firms, not to a firm facing a downward-sloping demand curve where each extra unit also lowers the price on all units sold.",
  "ExplanationWrongA": "",
  "ExplanationWrongB": "8,000 units comes from setting PRICE equal to marginal cost: 60 − 0.005Q = 20 → Q = 8,000. For a firm with market power this ignores the revenue lost on inframarginal units — every additional unit lowers the price on ALL units sold, so marginal revenue ($60 − $0.01Q) lies below price. At 8,000 units the price falls to $20, equal to marginal cost, and marginal revenue is deeply negative; profit is far below the maximum earned at 4,000 units.",
  "ExplanationWrongC": "6,000 units comes from maximizing REVENUE rather than profit: MR = 0 → 60 − 0.01Q = 0 → Q = 6,000. Revenue peaks there, but profit does not — the 6,000th unit adds zero revenue while costing $20, so profit is already falling by that point. Profit maximization sets MR equal to MC ($20), not to zero.",
  "ExplanationWrongD": "2,000 units results from solving with an incorrect marginal cost: 60 − 0.01Q = 40 → Q = 2,000, or from a decimal slip (0.01Q = 20 → Q = 2,000 instead of 4,000). The stated marginal cost is $20 per unit, which yields 60 − 0.01Q = 20 → Q = 4,000 units.",
  "FormulaReference": "MR = MC: for linear demand P = a − bQ, MR = a − 2bQ; set MR = MC",
