  "DifficultyScore": 3,
  "ExplanationCorrect": "ROI-based pricing adds a target return on the invested asset base to unit cost. The required profit is 15% × $2,000,000 = $300,000 per year. Spread over the planned 50,000 units, the profit markup is $300,000 ÷ 50,000 = $6.00 per unit. Target price = $30 + $6.00 = $36.00. Harborpoint must price at $36.00 to earn a 15% return on its $2 million investment at the planned volume. The formula is price = unit cost + (target ROI × investment) ÷ volume. A common error is applying the ROI percentage directly to unit cost ($30 × 1.15 = $34.50) — the return must be computed on the ASSET BASE, not on cost per unit.",
  "ExplanationWrongA": "$34.50 is $30 × 1.15 — a cost-plus markup of 15% on unit cost. The 15% target applies to the $2,000,000 INVESTMENT, which generates a $300,000 return requirement, not to the $30 unit cost (which would generate only $4.50 per unit). Dividing the correct $300,000 by 50,000 units yields a $6.00 markup and a $36.00 price.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "$33.00 results from using half the required return: $30 + ($150,000 ÷ 50,000) = $30 + $3.00 = $33.00. The full target is 15% × $2,000,000 = $300,000, so the per-unit markup is $6.00, not $3.00. A candidate reaching this answer has applied roughly a 7.5% return or halved the investment base.",
  "ExplanationWrongD": "$45.00 is $30 × 1.50 — a 50% markup with no basis in the data. The ROI requirement of 15% on the $2,000,000 investment is $300,000 total, which is a $6.00 markup per unit at 50,000 units, giving $36.00. A candidate reaching $45.00 has treated the markup percentage as 50% rather than deriving the markup from the asset base and volume.",
