  "ExplanationCorrect": "A cost-plus transfer price applies the division's markup to the agreed cost base. Alder Motors' policy specifies FULL cost plus 25%, and full cost is $40 per unit. Transfer price = $40 × 1.25 = $50.00. The $50 price covers the Engine Division's full cost and provides a $10 markup per unit. Note that the policy defines the base — using variable cost ($30 × 1.25 = $37.50) would violate the stated full-cost basis even though the arithmetic is clean. A common error is reporting the markup alone ($10) or treating the 25% as a dollar add-on ($40 + 25 = $65).",
  "ExplanationWrongA": "$10.00 is the markup, not the price ($40 × 25% = $10). The transfer price must include the cost base: $40 + $10 = $50.00. A candidate reaching this answer has stopped at the margin and forgotten to add the full cost the markup attaches to.",
  "ExplanationWrongB": "$30.00 is the variable cost. The policy specifies FULL cost as the base, which is $40, and the 25% markup applies to that figure. Using variable cost would produce $30 × 1.25 = $37.50, but that base violates Alder's stated policy and understates the price the Engine Division is entitled to charge.",
  "ExplanationWrongC": "$65.00 treats the 25% markup as a $25 dollar add-on ($40 + 25). The markup is a PERCENTAGE of the base: 25% × $40 = $10, giving $40 + $10 = $50.00, not $65.00. A candidate reaching this answer has misread the percentage as a flat dollar amount.",
  "ExplanationWrongD": "",
  "FormulaReference": "Cost-plus transfer price = Full Cost × (1 + Markup %)",
