  "ExplanationCorrect": "Relevant costing evaluates only the incremental cash flows of the special order. Incremental revenue: 5,000 × $18 = $90,000. Incremental variable cost: 5,000 × $15 = $75,000. Incremental contribution: $90,000 − $75,000 = $15,000. One-time setup: $10,000. Net effect = $15,000 − $10,000 = +$5,000. Pioneer Packaging should ACCEPT: operating income rises by $5,000. The normal selling price of $25 is irrelevant — it is a benchmark, not a cost, and with idle capacity the order does not disturb regular sales. A common error is ignoring the one-time setup cost, or rejecting the order simply because the price is below the normal price.",
  "ExplanationWrongA": "",
  "ExplanationWrongB": "$15,000 is the contribution BEFORE the setup cost (5,000 × $3). The one-time setup of $10,000 must be deducted, leaving a $5,000 net gain. A candidate reaching this answer has stopped the calculation one step early and overstated the order's profitability by the full setup amount.",
  "ExplanationWrongC": "This counts the $10,000 setup against NOTHING — ignoring that the order also brings in 5,000 × $3 = $15,000 of contribution. Net of both flows, the order adds $5,000. The setup cost alone does not make the order unprofitable; it must be compared to the contribution the order generates.",
  "ExplanationWrongD": "The $25 normal price is irrelevant to a one-time order on idle capacity. What matters is whether incremental revenue covers incremental costs. At $18, each unit contributes $3, totaling $15,000, which covers the $10,000 setup with $5,000 to spare. Rejecting on the normal-price comparison would pass up $5,000 of profit.",
