  "ExplanationCorrect": "Relevant costing compares the total relevant cost of each alternative. Make: (10,000 × $12) + $40,000 = $160,000. Outsource: purchase cost is 10,000 × $15 = $150,000, and the released space can be rented for $25,000, which REDUCES the net cost of outsourcing to $150,000 − $25,000 = $125,000. Silverline saves $160,000 − $125,000 = $35,000 by outsourcing. The rental income is an opportunity benefit of the buy alternative, not a cost. A common error is ignoring the $25,000 rent entirely (concluding make is cheaper at $160,000 versus $150,000) or ADDING the rent to the purchase price instead of subtracting it.",
  "ExplanationWrongA": "The $150,000 purchase price is not the final number — the released space earns $25,000 of rent that makes the net cost of outsourcing $125,000, which is $35,000 below the $160,000 cost to make. A candidate reaching this answer has compared the gross purchase price to the make cost and forgotten the opportunity benefit of the freed space.",
  "ExplanationWrongB": "Rental income REDUCES the cost of the buy alternative; it is not added to it. The correct net buy cost is $150,000 − $25,000 = $125,000, not $175,000. Adding the rent to the purchase price reverses the sign of the opportunity benefit and flips the decision against outsourcing.",
