  "DifficultyScore": 3,
  "ExplanationCorrect": "Relevant costing requires identifying ALL costs that change with the decision, and outsourcing changes far more than the purchase price. Westgate must add the costs of qualifying and monitoring suppliers, managing contracts, inbound freight, and coordination, plus harder-to-quantify losses: the in-house know-how that leaves with the process and the difficulty of reversing the decision. These hidden costs frequently exceed the quoted price advantage. The controller's warning is that the price comparison alone is incomplete, not that outsourcing is always wrong. A common error is treating the supplier's quote as the total cost of the buy alternative — the quote is only the visible tip of the cost structure.",
  "ExplanationWrongA": "The quoted price covers only the supplier's charge. Westgate will also incur monitoring, coordination, freight, and contract-management costs, and will give up in-house knowledge that may be costly to rebuild. Treating the quote as the total cost systematically understates the buy alternative and can turn an apparently profitable outsourcing decision into a loss.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "Contractually the supplier may be liable, but Westgate's customers experience defects as Westgate's problem. The buyer still bears the costs of specifying quality, monitoring compliance, managing disputes, and repairing customer relationships. Outsourcing moves the work, not the accountability for its outcome.",
  "ExplanationWrongD": "Outsourcing usually DEMANDS more management attention, not less: negotiating and enforcing contracts, managing the relationship, and coordinating schedules and quality across company boundaries. Westgate's managers cannot walk away from a process simply because someone else now performs it.",
