  "ExplanationCorrect": "Relevant costing compares the total cash flows of each alternative over their common horizon. Selling yields $500,000 now. Leasing yields $60,000 × 10 years = $600,000. Per the board's instruction to set aside the time value of money, the lease is superior by $100,000, and CedarPoint should lease. A full analysis would discount the lease stream (comparing $500,000 today with $60,000 annually requires a discount rate), but on the total-cash basis specified, leasing wins. A common error is preferring the sale on the general principle that cash today is better, without quantifying the $100,000 difference between the alternatives.",
  "ExplanationWrongA": "Cash today being preferable is a time-value argument, and this analysis explicitly sets time value aside. On total cash, the lease brings $600,000 versus $500,000 — $100,000 more. The candidate has asserted a principle without doing the arithmetic the decision requires.",
