  "ExplanationWrongA": "There is no after-tax profit per unit at breakeven — profit is zero, so the tax is zero. The tax rate changes how much of EACH DOLLAR of profit is kept, but at breakeven there are no profit dollars to tax. Granite State's breakeven volume is unaffected by the rate change.",
