  "Difficulty": "Moderate",
  "DifficultyScore": 3,
  "ExplanationCorrect": "Under pricing strategy theory, bundling converts a distribution of reservation prices into one price that captures more consumer surplus. It is most powerful when reservation prices are NEGATIVELY correlated — one customer values the spreadsheet highly and the database little, while another has the opposite pattern. Selling separately at high prices earns little; a bundle price near the sum of the two moderate valuations captures both customers' surplus. Nimbus chooses between pure bundling (only the bundle is sold) and mixed bundling (the bundle plus individual products), whichever extracts more value. A common error is assuming bundling always works — with positively correlated valuations it adds little, and a bad bundle price can reduce revenue below separate pricing.",
  "ExplanationWrongA": "The opposite is true. Nimbus's gain is largest when valuations are NEGATIVELY correlated, because a bundle averages out the differences across customers. With positive correlation, all customers value both products similarly, and bundling adds little over separate pricing.",
  "ExplanationWrongB": "Bundling can reduce revenue if the bundle price is set poorly or if customers who would have bought both products anyway now pay a discounted bundle price. Nimbus must test whether the bundle beats the sum of separate sales; the outcome is an empirical question, not a guarantee.",
  "ExplanationWrongC": "Bundling is a routine commercial practice — software suites, cable packages, and meal deals are legal. Antitrust concerns arise only in specific anticompetitive contexts (such as tying by a dominant firm), not from bundling itself. The claim of per se illegality overstates the law.",
