  "ExplanationCorrect": "The order converts at today's rate of 0.75 US$/C$ to C$100,000 × 0.75 = $75,000. The U.S. dollar is expected to weaken 2% by the payment date 60 days out, so each Canadian dollar will buy fewer U.S. dollars: 0.75 × 0.98 = 0.735, giving C$100,000 × 0.735 = $73,500. Against variable costs of $60,000, the expected net contribution is $73,500 − $60,000 = +$13,500. Vantage should ACCEPT — even the adverse currency move leaves a healthy margin, and the 2% exposure could be hedged with a forward contract to lock in close to $15,000. A common error is pricing the order at the spot rate and ignoring the projected move, or rejecting any order that carries exchange exposure.",
  "ExplanationWrongA": "$15,000 assumes the spot rate survives to settlement — it ignores the projected 2% weakening of the U.S. dollar, which cuts the conversion to $73,500 and the net contribution to $13,500. The decision is still to accept, but $15,000 overstates the expected margin Vantage should plan against.",
