  "ExplanationCorrect": "Yield management maximizes revenue from FIXED, PERISHABLE capacity — Skyway's seats evaporate the moment the flight departs, so unsold inventory can never be recovered. The tool segments customers by willingness to pay and by booking behavior: price-sensitive leisure travelers book early at low fares, while business travelers book late and pay more, and prices rise as remaining capacity shrinks and departure nears. Because the same seat can be sold at many prices over time, this is price discrimination across time and customer type. A common error is thinking uniform pricing is optimal — one price either leaves low-fare customers unbought or sells premium seats too cheaply, both of which destroy revenue on fixed capacity.",
  "ExplanationWrongA": "A single price leaves revenue on the table: it is too high for leisure travelers Skyway could fill empty seats with, and too low for business travelers who would pay more near departure. Segmenting the perishable capacity captures revenue from both groups that a uniform price cannot reach.",
  "ExplanationWrongB": "Discounting is only one side of the strategy. Yield management also RAISES prices for late-booking, high-willingness-to-pay customers and allocates scarce seats toward higher fares as the flight fills. It manages the whole price path, not just the cheap end.",
  "ExplanationWrongC": "The capacity is fixed — that is the point. Skyway cannot add seats, so the only lever is pricing the existing inventory across segments and over time. If capacity were variable, the firm could chase demand with quantity instead of price.",
