  "CorrectChoice": "B",
  "Difficulty": "Moderate",
  "DifficultyScore": 3,
  "ExplanationCorrect": "Relevant costing compares the avoidable cost of each production plan. Level production avoids 10,000 hours of overtime at a $6 premium: 10,000 × $6 = $60,000 saved. But smoothing production requires carrying 20,000 units of inventory at $4 each: 20,000 × $4 = $80,000 of carrying cost. Because $80,000 exceeds $60,000, the SEASONAL plan with overtime is cheaper by $20,000, and Lakeside Toys should follow seasonal production. The comparison must be apples-to-apples: the overtime PREMIUM versus the total carrying cost of the inventory that level production creates. A common error is comparing overtime total wages (including the regular rate that would be paid either way) against carrying cost, or reversing the inequality between the two figures.",
  "ExplanationWrongA": "Level production avoids $60,000 of premium but CREATES $80,000 of carrying cost. Avoiding overtime is not free — it is purchased with inventory. Net of both effects, level production costs $20,000 MORE than the seasonal plan. The candidate has counted the saving without counting the cost that produces it.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "The comparison is reversed: the $80,000 carrying cost is ABOVE the $60,000 overtime premium, making seasonal production cheaper, not level production. The candidate has computed both amounts correctly but inverted the inequality and drawn the wrong conclusion.",
  "ExplanationWrongD": "The premium is $6 per hour, so 10,000 hours cost $60,000 — not $120,000, which would double-count the premium (for example, using $12 per hour). And $120,000 would still exceed the $80,000 carrying cost, so the miscomputed figure could not justify the seasonal plan anyway.",
