  "CorrectChoice": "B",
  "Difficulty": "Difficult",
  "DifficultyScore": 4,
  "ExplanationCorrect": "The margin of safety is the percentage by which sales can decline before operating income reaches zero. MOS = Operating Income / Contribution Margin = $300,000 / $900,000 = 33.3%. Cross-check with the DOL: DOL = CM / OI = $900,000 / $300,000 = 3.0, and the maximum decline before OI becomes zero is 100% / DOL = 33.3%. The two measures agree: a 33.3% sales decline (to $1,333,333, exactly the breakeven point where CM equals the $600,000 of fixed costs) eliminates operating income. The board should understand that Atlas has a one-third cushion before losses begin.",
  "ExplanationWrongA": "15.0% is the operating margin ($300,000 / $2,000,000), a profitability measure, not a cushion measure. The margin of safety relates operating income to CONTRIBUTION margin because only contribution margin absorbs fixed costs. Using the operating margin understates the cushion and would misstate the downside risk to the board.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "45.0% is the contribution margin ratio ($900,000 / $2,000,000). The CM ratio describes how much of each sales dollar covers fixed costs and profit; it is not the percentage decline sales can absorb. The correct decline is OI / CM = 33.3%.",
  "ExplanationWrongD": "66.7% is fixed costs divided by contribution margin ($600,000 / $900,000). That ratio is the breakeven sales level as a fraction of current sales, not the decline percentage. The sales decline to breakeven is 1 − 66.7% = 33.3%.",
