  "CognitiveLevel": "Analyze",
  "CommonTrapReference": "Ignoring displaced regular sales when a special order exceeds idle capacity — every displaced unit loses its contribution margin, and sales commissions not paid on the special order reduce its variable cost.",
  "CorrectChoice": "A",
  "Difficulty": "Difficult",
  "DifficultyScore": 4,
  "ExplanationCorrect": "The order's relevant cost has two parts. First, the special order's variable cost excludes the $4 commission that is not paid on it: $50 − $4 = $46 per unit, so 2,000 × $46 = $92,000 against revenue of 2,000 × $62 = $124,000. Second, capacity is only 10,000 units and current sales are 9,000, so the 2,000-unit order displaces 1,000 units of regular sales. Lost contribution = 1,000 × ($90 − $50) = $40,000. Net effect = $124,000 − $92,000 − $40,000 = −$8,000. Beacon should reject the order; accepting it would reduce operating income by $8,000.",
  "ExplanationWrongA": "",
  "ExplanationWrongB": "+$32,000 counts the commission savings but ignores the displacement: $124,000 − $92,000 = $32,000. Because the order crowds out 1,000 units of $40-margin regular business, the apparent gain of $32,000 is more than offset — the true net effect is a loss of $8,000.",
  "ExplanationWrongC": "−$16,000 uses the full $50 variable cost (including the commission that the special order does not pay) AND counts the displacement: $124,000 − $100,000 − $40,000 = −$16,000. The commission savings of $4 per unit on all 2,000 units is real and must be included, making the net loss only $8,000.",
  "ExplanationWrongD": "+$24,000 ignores BOTH the commission savings and the displacement: $124,000 − (2,000 × $50) = $24,000. Neither of the two relevant adjustments is optional — the order is a money-loser when both are applied.",
  "FormulaReference": "DA-08: Incremental decision rule (Relevant costing variant)",
