  "ExplanationCorrect": "Compute the incremental margin per unit first: P yields $24 − $12 − $8 = +$4 per unit; Q yields $26 − $18 − $10 = −$2 per unit, so Q is never processed. P uses 2 machine hours per unit, so its incremental margin per constrained hour is $4 / 2 = $2. With 400 hours available, only 200 units of P can be processed: 200 × $4 = $800 incremental profit. Q is sold at split-off. The controller should report a maximum incremental profit of $800 — the constraint, not the per-unit margin, drives the decision.",
