  "CorrectChoice": "C",
  "Difficulty": "Moderate",
  "DifficultyScore": 3,
  "ExplanationCorrect": "The book value of the old machine is sunk and irrelevant as a cash flow, but it matters for taxes. Disposal proceeds are $15,000 against a $40,000 book value, producing a $25,000 loss that shields $25,000 × 25% = $6,250 of taxes. After-tax disposal cash = $15,000 + $6,250 = $21,250. Net initial outlay = $90,000 − $21,250 = $68,750. The annual operating savings and terminal salvage differences would be evaluated separately for the full decision, but the question asks only for the net initial cash outlay attributable to replacing the machine.",
  "ExplanationWrongA": "$75,000 is $90,000 − $15,000, which ignores the tax benefit of the disposal loss. The $25,000 book loss shields $6,250 of taxes, so the old machine's disposal contributes $21,250 of cash, not $15,000.",
  "ExplanationWrongB": "$71,250 treats the $40,000 book value as an outflow and then adds the tax benefit: $90,000 − $40,000 + $15,000 + $6,250. The book value itself is never a cash flow — it enters only through the tax effect on the gain or loss.",
  "ExplanationWrongC": "",
