  "CognitiveLevel": "Apply",
  "CommonTrapReference": "Confusing cost-based pricing with value-based pricing — value-based pricing sets the price from the customer's willingness to pay, with cost serving only as the floor, not the starting point.",
  "CorrectChoice": "A",
  "Difficulty": "Moderate",
  "DifficultyScore": 3,
  "ExplanationCorrect": "Value-based pricing starts from the value the customer perceives, not from cost. The customer survey shows $210 of perceived value; the cost floor is $140 and the competitor charges $180. A price of $195 captures nearly all of the perceived value while undercutting the competitor — it also leaves a $55 margin per unit, far above the $14 margin of a 10% cost-plus price. Cost-based approaches like $140 or $154 leave value on the table, and $225 exceeds the customer's willingness to pay. Value-based pricing is appropriate here because customer economics (lifetime savings), not production cost, determine what the product is worth.",
  "ExplanationWrongA": "",
  "ExplanationWrongB": "$140 is the cost floor. Pricing at cost is cost-based pricing's extreme: it guarantees no loss but captures none of the $210 of value the customer perceives. Value-based pricing deliberately prices between cost and perceived value to share the surplus.",
  "ExplanationWrongC": "$154 is a cost-plus price ($140 × 1.10). Cost-plus ignores the demand side entirely — the customer is willing to pay $210 and the competitor charges $180, so $154 sacrifices margin without a strategic reason.",
  "ExplanationWrongD": "$225 exceeds the customer's perceived value of $210. No rational customer pays more than the value received; this price would destroy demand. Value-based pricing never exceeds the willingness to pay.",
