  "ExplanationCorrect": "A price cut must be volume-justified against the contribution it destroys. Current contribution per unit = $80 − $50 = $30, and current total contribution = $30 × 20,000 = $600,000. After the cut to $72, the new margin is $72 − $50 = $22. To preserve the same total contribution: required volume = $600,000 / $22 = 27,272.7, so 27,273 units. In percentage terms, volume must rise 36.4% — far more than the 10% price cut — because the margin fell by 26.7% ($30 to $22). If management does not believe 27,273 units is achievable, the price cut should be rejected.",
  "ExplanationWrongA": "22,000 units assumes volume rises in proportion to the price cut (10%), which is the classic elasticity error. Because the margin per unit fell 26.7%, a mere 10% volume increase leaves total contribution at 22,000 × $22 = $484,000 — a $116,000 shortfall against the current $600,000.",
  "ExplanationWrongB": "",
