  "ExplanationWrongA": "+$120,000 double-counts the avoidable fixed costs: it adds the $50,000 segment margin and the $70,000 redeployment as if both were gains. Dropping forfeits the $50,000 margin and gains $70,000 — the net improvement is $20,000, not $120,000.",
