  "CognitiveLevel": "Apply",
  "CommonTrapReference": "Ranking products by throughput per unit or by price per minute instead of by throughput per minute of the constrained resource.",
  "CorrectChoice": "A",
  "Difficulty": "Moderate-Easy",
  "DifficultyScore": 2,
  "ExplanationCorrect": "Throughput accounting ranks products by throughput per minute of the bottleneck. Throughput = selling price minus truly variable cost (direct materials). Product A: $300 − $120 = $180 over 30 minutes = $6.00 per minute. Product B: $200 − $60 = $140 over 20 minutes = $7.00 per minute. B generates $1.00 more throughput per bottleneck minute, so the scheduler should prioritize B at the constrained workstation. Per-unit throughput is misleading here: A has the higher unit throughput but consumes 50% more constraint time.",
  "ExplanationWrongA": "",
  "ExplanationWrongB": "$10.00 per minute divides the SELLING PRICE by constraint minutes (300/30 and 200/20). Throughput accounting subtracts truly variable cost before dividing — material cost matters, and including it changes the ranking in favor of B.",
  "ExplanationWrongC": "$4.00 and $3.00 divide direct MATERIAL cost by minutes (120/30 and 60/20), which measures material intensity, not throughput. The correct numerators are price minus material: $180 for A and $140 for B.",
  "ExplanationWrongD": "$180.00 and $140.00 are throughput per UNIT without dividing by constraint time. A's unit advantage disappears once time is considered: $6.00 versus $7.00 per minute favors B.",
  "FormulaReference": "DA-06 variant: Throughput per constraint minute",
  "ItemStyle": "single-select",
