  "BlueprintDomain": "Decision Analysis",
  "CalculationItem": true,
  "Choices": {
    "A": "$45 per hour — product X's contribution margin per unit",
    "B": "$15 per hour — the additional contribution from one more machine hour at the optimal solution",
    "C": "$20 per hour — product Y's contribution margin per machine hour",
    "D": "$30 per hour — product Y's contribution margin per unit"
  },
  "CognitiveLevel": "Apply",
  "CommonTrapReference": "Confusing the shadow price with a product's contribution margin per unit or per hour — the shadow price is the marginal value of relaxing the BINDING constraint at the optimum.",
  "CorrectChoice": "B",
  "Difficulty": "Moderate",
  "DifficultyScore": 3,
  "ExplanationCorrect": "The shadow price of a constraint is the change in the objective (contribution margin) from relaxing that constraint by one unit — but only at the optimum and only if the constraint is binding. The machine-hour constraint (3X + 1.5Y ≤ 600) is binding at the optimum (X = 50, Y = 300), while the demand caps for both products are not. An additional machine hour is used to produce one-third more of X (X needs 3 hours), adding $45 / 3 = $15 of contribution. Since Y's demand cap is exhausted, extra hours cannot produce more Y. The shadow price is therefore $15 per machine hour — the maximum rational payment for one additional hour of bottleneck capacity.",
  "ExplanationWrongA": "$45 is X's contribution margin per UNIT. One additional machine hour produces only one-third of a unit of X, worth $15. Quoting the unit margin as the hourly value overstates the capacity's worth threefold.",
  "ExplanationWrongB": "",
  "ExplanationWrongC": "$20 is Y's contribution margin per machine hour ($30 / 1.5 hours), the ranking metric for the initial mix decision. It is not the shadow price because Y is already at its demand cap of 300 units — extra hours cannot be used for Y, so the marginal hour is worth only X's $15.",
  "ExplanationWrongD": "$30 is Y's contribution margin per unit. Y's demand cap binds at 300 units, so additional machine hours add zero Y units. The only product that can absorb extra hours is X, at $15 per hour.",
  "FormulaReference": "DA-06 variant: Linear programming shadow price",
  "ItemStyle": "single-select",
  "LOSTag": "C.5",
  "Part": 2,
  "Part2OnlyFlag": true,
  "QuestionID": "P2-C-088",
  "Section": "C",
  "Stem": "Operations Analyst Priya Nair at Vertex Fabrication solves a product-mix linear program: maximize 45X + 30Y subject to 3X + 1.5Y ≤ 600 machine hours, X ≤ 150 units, and Y ≤ 300 units. The optimum is X = 50, Y = 300, with contribution of $11,250, and the machine-hour constraint is binding. Management can rent additional machine hours and asks Ms. Nair for the shadow price of machine capacity. What is it?",
