  "ExplanationCorrect": "Value the two strategies separately. Commit now: expected value = (0.60 × $6,000,000) + (0.40 × −$4,000,000) = $3,600,000 − $1,600,000 = $2,000,000. Pilot first: pay $300,000, and commit the $2,000,000 investment only if the pilot succeeds (60%). Expected value = −$300,000 + 0.60 × ($6,000,000 − $2,000,000) + 0.40 × $0 = −$300,000 + $2,400,000 = $2,100,000. The pilot option is worth $2,100,000 − $2,000,000 = $100,000: the flexibility to avoid the $4,000,000 failure outcome, net of the pilot's cost and the 40% of trials where the pilot still fails after being paid for. The board should pilot rather than commit.",
