  "ExplanationCorrect": "Quantify both sides. Annual savings = 50,000 × ($40 − $36) = $200,000; over three years, $600,000. The in-house alternative requires a $1,200,000 equipment investment, so staying in-house costs at least that amount in the first three years — far more than outsourcing. The main risk of outsourcing is single-supplier dependence: switching back costs $250,000, but a 3-year contract with a dual-source clause caps that exposure. The year-to-year option forfeits $400,000 of locked-in savings and does not avoid the switching cost. The recommended judgment: outsource on a 3-year contract with dual sourcing, accepting the switching-back risk because the $600,000 savings dwarfs the $250,000 worst-case switching cost while the clause protects against supply failure.",
